javascript:
(function() {
  const state = {
    currentStep: 0,
    steps: [
      {
        title: "初始均衡状态",
        text: "假设经济中存在两类工人（高技能和低技能）和一系列任务。低技能工人在某些低阶任务（区间 I 到 I*）具有比较优势，与高技能工人共同工作；高技能工人还单独承担高阶任务（区间 I* 到 N）。此时，相对工资由两者共同工作的任务生产力比率 λH/λU 决定。",
        formula: "w_H / w_L = λ_H / λ_L",
        source: "S652"
      },
      {
        title: "AI 冲击：低技能生产力提升",
        text: "AI 技术进步提高了低技能工人在其优势任务区间（I 到 I*）的生产力，使得 λH/λU 比率下降（即低技能相对效率提升）。直观上这似乎应缩小工资差距。",
        formula: "λ_L ↑  ⇒  (λ_H / λ_L) ↓",
        source: "S654"
      },
      {
        title: "价格效应与劳动力重配",
        text: "由于任务间替代弹性 σ < 1，生产力的提高导致这些任务的价格大幅下降，减少了对该区间劳动力的总需求。高技能工人因此完全退出这些低阶任务，全部转移到高阶任务区间（I* 到 N）。",
        formula: "σ < 1  ⇒  Price ↓↓  ⇒  Demand for Labor ↓",
        source: "S654"
      },
      {
        title: "新的均衡与不平等加剧",
        text: "现在，高低技能工人共同工作的任务区间变成了高阶任务（I* 到 N）。在这些任务中，高技能工人原本就具有更高的相对生产力（ω > λH/λU）。因此，新的相对工资由 ω 决定，高于原来的 λH/λU，导致技能间不平等反而上升。",
        formula: "w_H / w_L = ω  (where ω > λ_H / λ_L)",
        source: "S662"
      }
    ]
  };

  const svgGroup = document.getElementById('dynamic-content');
  const titleEl = document.getElementById('stage-title');
  const textEl = document.getElementById('stage-text');
  const formulaEl = document.getElementById('wage-formula');
  const indicatorEl = document.getElementById('stage-indicator');
  const btnNext = document.getElementById('btn-next');
  const btnPrev = document.getElementById('btn-prev');
  const btnReset = document.getElementById('btn-reset');

  function renderStep(index) {
    const step = state.steps[index];

    // Update Text
    titleEl.textContent = step.title;
    textEl.textContent = step.text;
    formulaEl.textContent = step.formula;
    indicatorEl.textContent = `阶段 ${index + 1}/4：${step.title}`;

    // Clear SVG
    svgGroup.innerHTML = '';

    // Common constants
    const yBase = 350;
    const xStart = 50;
    const xEnd = 750;
    const totalWidth = xEnd - xStart;
    const iStarRatio = 0.45; // Position of I*
    const xIStar = xStart + totalWidth * iStarRatio;

    // Draw Axis Labels
    const axisGroup = document.createElementNS("http://www.w3.org/2000/svg", "g");
    axisGroup.innerHTML = `
      <line x1="${xStart}" y1="${yBase}" x2="${xEnd}" y2="${yBase}" stroke="#999" stroke-width="2" />
      <text x="${xStart - 10}" y="${yBase + 20}" text-anchor="end" class="axis-label">I</text>
      <text x="${xEnd + 10}" y="${yBase + 20}" text-anchor="start" class="axis-label">N</text>
      <line x1="${xIStar}" y1="${yBase - 10}" x2="${xIStar}" y2="${yBase + 10}" stroke="#666" stroke-width="1" stroke-dasharray="4" />
      <text x="${xIStar}" y="${yBase + 35}" text-anchor="middle" class="axis-label" fill="#2C5F68">I*</text>
    `;
    svgGroup.appendChild(axisGroup);

    // Step-specific visualization
    if (index === 0) {
      // Initial: Low skill in [I, I*], High skill in [I, N]
      // Low Skill Bar (Orange)
      const lowBar = document.createElementNS("http://www.w3.org/2000/svg", "rect");
      lowBar.setAttribute("x", xStart);
      lowBar.setAttribute("y", yBase - 40);
      lowBar.setAttribute("width", xIStar - xStart);
      lowBar.setAttribute("height", 30);
      lowBar.setAttribute("fill", "#D97742");
      lowBar.setAttribute("class", "task-bar");
      lowBar.setAttribute("opacity", "0.8");
      svgGroup.appendChild(lowBar);

      const lowLabel = document.createElementNS("http://www.w3.org/2000/svg", "text");
      lowLabel.setAttribute("x", xStart + (xIStar - xStart)/2);
      lowLabel.setAttribute("y", yBase - 25);
      lowLabel.setAttribute("text-anchor", "middle");
      lowLabel.setAttribute("class", "text-label");
      lowLabel.setAttribute("fill", "#fff");
      lowLabel.textContent = "低技能 (L)";
      svgGroup.appendChild(lowLabel);

      // High Skill Bar (Teal) - Full width but transparent in [I, I*] to show overlap
      const highBar = document.createElementNS("http://www.w3.org/2000/svg", "rect");
      highBar.setAttribute("x", xStart);
      highBar.setAttribute("y", yBase - 80);
      highBar.setAttribute("width", totalWidth);
      highBar.setAttribute("height", 30);
      highBar.setAttribute("fill", "#2C5F68");
      highBar.setAttribute("class", "task-bar");
      highBar.setAttribute("opacity", "0.8");
      svgGroup.appendChild(highBar);

      const highLabel = document.createElementNS("http://www.w3.org/2000/svg", "text");
      highLabel.setAttribute("x", xStart + totalWidth/2);
      highLabel.setAttribute("y", yBase - 65);
      highLabel.setAttribute("text-anchor", "middle");
      highLabel.setAttribute("class", "text-label");
      highLabel.setAttribute("fill", "#fff");
      highLabel.textContent = "高技能 (H)";
      svgGroup.appendChild(highLabel);

      // Overlap indicator
      const overlapText = document.createElementNS("http://www.w3.org/2000/svg", "text");
      overlapText.setAttribute("x", xStart + (xIStar - xStart)/2);
      overlapText.setAttribute("y", yBase - 95);
      overlapText.setAttribute("text-anchor", "middle");
      overlapText.setAttribute("class", "text-label");
      overlapText.setAttribute("fill", "#666");
      overlapText.setAttribute("font-size", "10");
      overlapText.textContent = "共同工作区间 (决定工资)";
      svgGroup.appendChild(overlapText);

    } else if (index === 1) {
      // AI Shock: Low skill productivity up
      // Same layout but add arrows indicating productivity boost
      const lowBar = document.createElementNS("http://www.w3.org/2000/svg", "rect");
      lowBar.setAttribute("x", xStart);
      lowBar.setAttribute("y", yBase - 40);
      lowBar.setAttribute("width", xIStar - xStart);
      lowBar.setAttribute("height", 30);
      lowBar.setAttribute("fill", "#D97742");
      lowBar.setAttribute("class", "task-bar");
      lowBar.setAttribute("opacity", "0.8");
      svgGroup.appendChild(lowBar);

      const highBar = document.createElementNS("http://www.w3.org/2000/svg", "rect");
      highBar.setAttribute("x", xStart);
      highBar.setAttribute("y", yBase - 80);
      highBar.setAttribute("width", totalWidth);
      highBar.setAttribute("height", 30);
      highBar.setAttribute("fill", "#2C5F68");
      highBar.setAttribute("class", "task-bar");
      highBar.setAttribute("opacity", "0.8");
      svgGroup.appendChild(highBar);

      // Productivity Arrows
      for(let i=0; i<5; i++) {
        const arrowX = xStart + (xIStar - xStart) * (0.1 + i*0.2);
        const arrow = document.createElementNS("http://www.w3.org/2000/svg", "path");
        arrow.setAttribute("d", `M${arrowX},${yBase - 50} L${arrowX},${yBase - 85}`);
        arrow.setAttribute("stroke", "#D97742");
        arrow.setAttribute("stroke-width", "2");
        arrow.setAttribute("marker-end", "url(#arrow-head)");
        svgGroup.appendChild(arrow);
      }

      const boostText = document.createElementNS("http://www.w3.org/2000/svg", "text");
      boostText.setAttribute("x", xStart + (xIStar - xStart)/2);
      boostText.setAttribute("y", yBase - 95);
      boostText.setAttribute("text-anchor", "middle");
      boostText.setAttribute("class", "text-label");
      boostText.setAttribute("fill", "#D97742");
      boostText.setAttribute("font-weight", "bold");
      boostText.textContent = "AI 提升低技能生产力";
      svgGroup.appendChild(boostText);

    } else if (index === 2) {
      // Reallocation: High skill leaves [I, I*]
      // Low Skill stays
      const lowBar = document.createElementNS("http://www.w3.org/2000/svg", "rect");
      lowBar.setAttribute("x", xStart);
      lowBar.setAttribute("y", yBase - 40);
      lowBar.setAttribute("width", xIStar - xStart);
      lowBar.setAttribute("height", 30);
      lowBar.setAttribute("fill", "#D97742");
      lowBar.setAttribute("class", "task-bar");
      lowBar.setAttribute("opacity", "0.8");
      svgGroup.appendChild(lowBar);

      const lowLabel = document.createElementNS("http://www.w3.org/2000/svg", "text");
      lowLabel.setAttribute("x", xStart + (xIStar - xStart)/2);
      lowLabel.setAttribute("y", yBase - 25);
      lowLabel.setAttribute("text-anchor", "middle");
      lowLabel.setAttribute("class", "text-label");
      lowLabel.setAttribute("fill", "#fff");
      lowLabel.textContent = "仅低技能";
      svgGroup.appendChild(lowLabel);

      // High Skill moves to [I*, N]
      const highBar = document.createElementNS("http://www.w3.org/2000/svg", "rect");
      highBar.setAttribute("x", xIStar);
      highBar.setAttribute("y", yBase - 80);
      highBar.setAttribute("width", xEnd - xIStar);
      highBar.setAttribute("height", 30);
      highBar.setAttribute("fill", "#2C5F68");
      highBar.setAttribute("class", "task-bar");
      highBar.setAttribute("opacity", "0.8");
      // Animate entry
      highBar.setAttribute("transform", "translate(-50, 0)");
      highBar.style.transition = "transform 0.6s ease-out";
      setTimeout(() => highBar.setAttribute("transform", "translate(0,0)"), 50);
      svgGroup.appendChild(highBar);

      const highLabel = document.createElementNS("http://www.w3.org/2000/svg", "text");
      highLabel.setAttribute("x", xIStar + (xEnd - xIStar)/2);
      highLabel.setAttribute("y", yBase - 65);
      highLabel.setAttribute("text-anchor", "middle");
      highLabel.setAttribute("class", "text-label");
      highLabel.setAttribute("fill", "#fff");
      highLabel.textContent = "高技能转移至此";
      svgGroup.appendChild(highLabel);

      // Fade out area [I, I*] for High Skill
      const ghostBar = document.createElementNS("http://www.w3.org/2000/svg", "rect");
      ghostBar.setAttribute("x", xStart);
      ghostBar.setAttribute("y", yBase - 80);
      ghostBar.setAttribute("width", xIStar - xStart);
      ghostBar.setAttribute("height", 30);
      ghostBar.setAttribute("fill", "#eee");
      ghostBar.setAttribute("stroke", "#ccc");
      ghostBar.setAttribute("stroke-dasharray", "4");
      svgGroup.appendChild(ghostBar);

    } else if (index === 3) {
      // New Equilibrium: Overlap at [I*, N]
      // Low Skill expands to [I, N] (conceptually competing everywhere, but specifically overlapping at high end)
      // Visual: Low skill in [I, I*] (Orange) AND [I*, N] (Orange)
      // High skill in [I*, N] (Teal)

      // Low Skill Left
      const lowBarLeft = document.createElementNS("http://www.w3.org/2000/svg", "rect");
      lowBarLeft.setAttribute("x", xStart);
      lowBarLeft.setAttribute("y", yBase - 40);
      lowBarLeft.setAttribute("width", xIStar - xStart);
      lowBarLeft.setAttribute("height", 30);
      lowBarLeft.setAttribute("fill", "#D97742");
      lowBarLeft.setAttribute("class", "task-bar");
      lowBarLeft.setAttribute("opacity", "0.6");
      svgGroup.appendChild(lowBarLeft);

      // Low Skill Right (Overlap Zone)
      const lowBarRight = document.createElementNS("http://www.w3.org/2000/svg", "rect");
      lowBarRight.setAttribute("x", xIStar);
      lowBarRight.setAttribute("y", yBase - 40);
      lowBarRight.setAttribute("width", xEnd - xIStar);
      lowBarRight.setAttribute("height", 30);
      lowBarRight.setAttribute("fill", "#D97742");
      lowBarRight.setAttribute("class", "task-bar");
      lowBarRight.setAttribute("opacity", "0.8");
      svgGroup.appendChild(lowBarRight);

      // High Skill Right (Overlap Zone)
      const highBarRight = document.createElementNS("http://www.w3.org/2000/svg", "rect");
      highBarRight.setAttribute("x", xIStar);
      highBarRight.setAttribute("y", yBase - 80);
      highBarRight.setAttribute("width", xEnd - xIStar);
      highBarRight.setAttribute("height", 30);
      highBarRight.setAttribute("fill", "#2C5F68");
      highBarRight.setAttribute("class", "task-bar");
      highBarRight.setAttribute("opacity", "0.8");
      svgGroup.appendChild(highBarRight);

      // Labels
      const overlapLabel = document.createElementNS("http://www.w3.org/2000/svg", "text");
      overlapLabel.setAttribute("x", xIStar + (xEnd - xIStar)/2);
      overlapLabel.setAttribute("y", yBase - 95);
      overlapLabel.setAttribute("text-anchor", "middle");
      overlapLabel.setAttribute("class", "text-label");
      overlapLabel.setAttribute("fill", "#333");
      overlapLabel.setAttribute("font-weight", "bold");
      overlapLabel.textContent = "新的共同工作区间";
      svgGroup.appendChild(overlapLabel);

      const wageLabel = document.createElementNS("http://www.w3.org/2000/svg", "text");
      wageLabel.setAttribute("x", xIStar + (xEnd - xIStar)/2);
      wageLabel.setAttribute("y", yBase - 115);
      wageLabel.setAttribute("text-anchor", "middle");
      wageLabel.setAttribute("class", "text-label");
      wageLabel.setAttribute("fill", "#D97742");
      wageLabel.textContent = "工资由 ω 决定 (更高)";
      svgGroup.appendChild(wageLabel);
    }
  }

  function updateControls() {
    btnPrev.disabled = state.currentStep === 0;
    btnPrev.style.opacity = state.currentStep === 0 ? "0.5" : "1";

    btnNext.disabled = state.currentStep === state.steps.length - 1;
    btnNext.style.opacity = state.currentStep === state.steps.length - 1 ? "0.5" : "1";
    btnNext.textContent = state.currentStep === state.steps.length - 1 ? "完成" : "下一步 →";
  }

  function goToStep(stepIndex) {
    if (stepIndex < 0 || stepIndex >= state.steps.length) return;
    state.currentStep = stepIndex;
    renderStep(stepIndex);
    updateControls();
  }

  btnNext.addEventListener('click', () => goToStep(state.currentStep + 1));
  btnPrev.addEventListener('click', () => goToStep(state.currentStep - 1));

  btnReset.addEventListener('click', () => {
    goToStep(0);
  });

  // Keyboard navigation
  document.addEventListener('keydown', (e) => {
    if (e.key === 'ArrowRight') goToStep(state.currentStep + 1);
    if (e.key === 'ArrowLeft') goToStep(state.currentStep - 1);
  });

  // Initialize
  renderStep(0);
  updateControls();
})();
